INSERT INTO "public"."projects" ("id", "name", "description", "detailed_description", "logo_url", "website", "organization_id", "is_public", "created_at", "payment_percentage", "payment_periodicity_id", "payment_custom_days", "default_payment_method_id", "category_id", "updated_at", "updated_by", "deleted_at", "status", "cumulative_revenue", "cumulative_donated", "email", "billing_email", "billing_frequency", "slug") VALUES
  ('12', 'Prime Depth Labs', 'Applied research studio building coordination tools for community-owned networks.', 'Prime Depth Labs prototypes software and governance patterns for digital communities that want to share upside more fairly. The studio experiments with contributor incentives, public accountability, and lightweight coordination tooling.', 'https://images.unsplash.com/photo-1516321318423-f06f85e504b3?q=80&w=2070&auto=format&fit=crop', 'https://primedepth.example.com', NULL, 't', '2025-05-06 08:03:38.034909+00', '1.00', '2', NULL, '4', '1', '2025-06-10 02:59:35.088824+00', NULL, NULL, 'active', '185000', '1850', 'hello@primedepth.example.com', 'finance@primedepth.example.com', 'monthly', 'prime-depth-labs'),
  ('3', 'Nomad Workspaces', 'Global network of sustainable co-working spaces for digital nomads.', 'Nomad Workspaces helps remote workers find welcoming, climate-aware workspaces while connecting them to local communities. Members can discover spaces, residency programs, and trusted hosts across the network.', 'https://images.unsplash.com/photo-1511632765486-a01980e01a18?q=80&w=2070&auto=format&fit=crop', 'https://nomadworkspace.example.org', '3', 't', '2025-02-07 05:33:50.708679+00', '1.40', '2', '30', '3', '13', '2025-06-10 02:58:44.438444+00', NULL, NULL, 'active', '420000', '5880', 'team@nomadworkspace.example.org', 'finance@nomadworkspace.example.org', 'monthly', 'nomad-workspaces'),
  ('4', 'GreenFinance', 'Ethical banking and investment platform focused on sustainability.', 'GreenFinance makes it easier for people and organizations to align their money with climate goals through transparent savings, lending, and impact reporting products.', 'https://images.unsplash.com/photo-1579621970795-87facc2f976d?q=80&w=2070&auto=format&fit=crop', 'https://greenfinance.example.com', '4', 't', '2024-12-07 05:33:50.708679+00', '1.00', '2', NULL, '2', '2', '2025-06-10 02:58:49.304259+00', NULL, NULL, 'active', '980000', '9800', 'hello@greenfinance.example.com', 'accounts@greenfinance.example.com', 'monthly', 'green-finance'),
  ('1', 'EcoStream', 'Sustainable video streaming platform with carbon-neutral infrastructure.', 'EcoStream helps values-aligned media teams host and distribute video without the usual platform trade-offs. It combines low-carbon infrastructure, subscriber support tools, and transparent impact reporting.', 'https://images.unsplash.com/photo-1485846234645-a62644f84728?q=80&w=2059&auto=format&fit=crop', 'https://ecostream.example.com', '1', 't', '2025-01-07 05:33:50.708679+00', '1.00', '2', NULL, '1', '5', '2025-06-10 04:19:01.372525+00', NULL, NULL, 'active', '1450000', '14500', 'team@ecostream.example.com', 'finance@ecostream.example.com', 'monthly', 'ecostream'),
  ('6', 'EduAccess', 'Affordable online education platform with income-sharing agreements.', 'EduAccess delivers cohort-based online learning with fair financing options, peer accountability, and pathways into mission-driven work.', 'https://images.unsplash.com/photo-1503676260728-1c00da094a0b?q=80&w=2022&auto=format&fit=crop', 'https://eduaccess.example.com', '6', 't', '2024-10-07 05:33:50.708679+00', '1.00', '2', NULL, '1', '3', '2025-06-10 02:59:00.283326+00', NULL, NULL, 'active', '760000', '7600', 'hello@eduaccess.example.com', 'finance@eduaccess.example.com', 'monthly', 'eduaccess'),
  ('2', 'Harvest', 'Farm-to-table marketplace connecting local farmers with consumers.', 'Harvest makes regional food systems more resilient by helping growers sell directly to nearby households, restaurants, and community buying clubs.', 'https://images.unsplash.com/photo-1444858291040-58f756a3bdd6?q=80&w=1978&auto=format&fit=crop', 'https://harvest.example.com', '2', 't', '2024-11-07 05:33:50.708679+00', '1.00', '2', NULL, '2', '7', '2025-06-10 02:58:37.195956+00', NULL, NULL, 'active', '640000', '6400', 'hello@harvest.example.com', 'billing@harvest.example.com', 'monthly', 'harvest'),
  ('7', 'LocalCraft', 'Marketplace for handmade goods from local artisans with sustainable practices.', 'LocalCraft helps artisan collectives reach nearby customers, tell the story behind their work, and offer fulfillment without platform lock-in.', 'https://images.unsplash.com/photo-1506806732259-39c2d0268443?q=80&w=2072&auto=format&fit=crop', 'https://localcraft.example.com', '7', 't', '2024-08-07 05:33:50.708679+00', '1.00', '2', NULL, '5', '6', '2025-06-10 02:59:04.645532+00', NULL, NULL, 'active', '510000', '5100', 'hello@localcraft.example.com', 'finance@localcraft.example.com', 'monthly', 'localcraft'),
  ('8', 'MindfulTech', 'Digital wellbeing tools and mindfulness applications for better mental health.', 'MindfulTech builds gentle digital products that help teams and individuals create healthier relationships with attention, work, and recovery.', 'https://images.unsplash.com/photo-1621228720536-e27ba8f4d363?q=80&w=2070&auto=format&fit=crop', 'https://mindfultech.example.com', '8', 't', '2024-12-07 05:33:50.708679+00', '1.00', '2', NULL, '1', '4', '2025-06-10 02:59:10.379785+00', NULL, NULL, 'active', '570000', '5700', 'hello@mindfultech.example.com', 'accounts@mindfultech.example.com', 'monthly', 'mindful-tech'),
  ('9', 'SolarShare', 'Community solar energy platform allowing users to invest in renewable energy.', 'SolarShare lets neighborhoods and local groups co-own solar infrastructure, follow project performance, and share the benefits of clean energy.', 'https://images.unsplash.com/photo-1558449028-b53a39d100fc?q=80&w=3000&auto=format&fit=crop', 'https://solarshare.example.com', '9', 't', '2024-09-07 05:33:50.708679+00', '1.00', '2', NULL, '2', '8', '2025-06-10 02:59:14.277946+00', NULL, NULL, 'active', '890000', '8900', 'hello@solarshare.example.com', 'billing@solarshare.example.com', 'monthly', 'solar-share'),
  ('10', 'Gigchain', 'Portable reputation and earnings tools for independent workers.', 'Gigchain helps freelancers and cooperatives keep a portable work history, coordinate referrals, and participate in shared safety nets across platforms.', 'https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?q=80&w=2070&auto=format&fit=crop', 'https://gigchain.example.com', NULL, 't', '2025-04-30 21:58:24.036389+00', '1.00', '2', NULL, '3', '11', '2025-06-10 02:59:18.681516+00', NULL, NULL, 'active', '215000', '2150', 'hello@gigchain.example.com', 'finance@gigchain.example.com', 'monthly', 'gigchain'),
  ('5', 'CarbonTrack', 'Personal carbon footprint tracking and offsetting app.', 'CarbonTrack helps people understand the emissions tied to their daily choices, then match those insights to practical reduction plans and trusted climate contributions.', 'https://images.unsplash.com/photo-1488415032361-b7e238421f1b?q=80&w=2069&auto=format&fit=crop', 'https://carbontrack.example.com', '5', 'f', '2025-03-07 05:33:50.708679+00', '1.00', '2', NULL, '2', '10', '2025-06-10 20:47:15.789579+00', NULL, NULL, 'active', '330000', '3300', 'hello@carbontrack.example.com', 'finance@carbontrack.example.com', 'monthly', 'carbon-track');
