  ('27', 'Clubhouse', 'clubhouse', 'Audio-first social app for live discussions and communities.', '0', '27', 'f'),
  ('1', 'Twitter (X)', 'twitter', 'The platform formerly known as Twitter. Microblogging and social commentary.', '0', '1', 't'),
