INSERT INTO "public"."team_roles" ("id", "title", "description", "created_at", "required_skills", "location", "tags") VALUES
  ('1', 'Chief Technology Officer (CTO)', 'Leads the technical vision of FundLoop, overseeing architecture, infrastructure, and engineering leadership. Defines the roadmap and ensures scalability, security, and maintainability.', '2025-04-10 05:27:04.735172+00', '{TypeScript,PostgreSQL,Next.js,Supabase,"Distributed Systems",Security}', 'Remote', '{leadership,engineering,core}'),
  ('2', 'Head of Product', 'Responsible for defining product vision, gathering requirements, prioritizing features, and ensuring user feedback drives continuous iteration. Works closely with design and engineering.', '2025-04-10 05:27:04.735172+00', '{Agile,Figma,"User Research","Product Management","Data Analysis"}', 'Remote', '{product,strategy}'),
  ('3', 'Lead Smart Contract Engineer', 'Designs, writes, and audits core smart contracts, particularly for fund management, staking, and identity. Ensures secure, upgradeable architecture.', '2025-04-10 05:27:04.735172+00', '{Solidity,Hardhat,EVM,ERC20/ERC721/ERC1155,Auditing}', 'Remote', '{engineering,blockchain,smart-contracts}'),
  ('4', 'Full Stack Engineer', 'Builds user-facing and backend features, integrates smart contracts, and supports the application’s evolution.', '2025-04-10 05:27:04.735172+00', '{Next.js,TailwindCSS,TypeScript,Supabase,tRPC,Prisma}', 'Remote', '{engineering,frontend,backend}'),
  ('5', 'DevOps & Security Engineer', 'Manages CI/CD pipelines, infrastructure (Vercel, Supabase, GCP), monitoring, and data security protocols.', '2025-04-10 05:27:04.735172+00', '{CI/CD,Docker,Vercel,Supabase,Cloudflare,OAuth,RLS}', 'Remote', '{engineering,devops,security}'),
  ('6', 'Protocol Designer', 'Defines economic and governance mechanisms, including incentives, reputation, UBI, and payout formulas.', '2025-04-10 05:27:04.735172+00', '{"Game Theory","Mechanism Design",Crypto-economics,"Math Modeling"}', 'Remote', '{governance,economics,protocol}'),
  ('7', 'Community Manager', 'Builds and nurtures FundLoop’s early adopter community. Manages Discord/Telegram, events, and onboarding guides.', '2025-04-10 05:27:04.735172+00', '{"Community Building","Social Media",Writing,"Public Speaking"}', 'Remote', '{community,support,growth}'),
  ('8', 'Head of Partnerships', 'Owns relationships with funders, DAOs, NGOs, and other public goods ecosystems. Develops win-win partnership models.', '2025-04-10 05:27:04.735172+00', '{Partnerships,Negotiation,"Ecosystem Strategy","Web3 Landscape"}', 'Remote', '{business,growth,strategy}'),
  ('9', 'UI/UX Designer', 'Designs intuitive, accessible, and beautiful interfaces for the FundLoop app. Translates complex flows into simple visuals.', '2025-04-10 05:27:04.735172+00', '{Figma,"User Flows",Accessibility,"Responsive Design"}', 'Remote', '{design,product,ux}'),
  ('10', 'Growth & Marketing Lead', 'Leads go-to-market strategy, brand positioning, social campaigns, SEO/SEM, and user acquisition.', '2025-04-10 05:27:04.735172+00', '{"Growth Marketing","Content Strategy",Analytics,SEO,Twitter/X}', 'Remote', '{marketing,growth,comms}'),
  ('11', 'Ecosystem Researcher', 'Surfaces opportunities and competitive intelligence. Tracks innovations in public goods, crypto, and adjacent ecosystems.', '2025-04-10 05:27:04.735172+00', '{Research,Writing,"Data Analysis","Web3 Landscape"}', 'Remote', '{research,strategy,intel}'),
  ('12', 'Technical Writer & Docs Lead', 'Owns and maintains all user and developer documentation, SDK walkthroughs, and onboarding content.', '2025-04-10 05:27:04.735172+00', '{Markdown,Docsify,GitBook,APIs,Communication}', 'Remote', '{writing,developer-relations,docs}'),
  ('13', 'Customer Success Lead', 'Ensures our users (creators, donors, contributors) have a seamless onboarding and support experience.', '2025-04-10 05:27:04.735172+00', '{Support,CRM,"Onboarding Design","Problem Solving"}', 'Remote', '{support,community,growth}'),
  ('14', 'Operations Manager', 'Manages the internal processes, compliance, finances, OKRs, and daily rhythm of the organization.', '2025-04-10 05:27:04.735172+00', '{Operations,"Project Management",Compliance,Finance}', 'Remote', '{ops,strategy,admin}');
